style.css:
@keyframes moveBackground {
    0% { background-position: 0 0; }
    100% { background-position: 100% 100%; }
}

body {
    background: url('https://i.pinimg.com/originals/72/88/52/728852438fe0c6d6568ce31f5fc01995.gifbackground') no-repeat center center fixed;
    background-size: cover;
    animation: moveBackground 30s infinite linear;
    font-family: 'Arial', sans-serif;
    color: white;
    margin: 0;
    padding: 0;
}

h1 {
    text-align: center;
    font-size: 3rem;
    margin-top: 20%;
}
